  "claim": {
    "component_id": "C051",
    "value": "When evidence supports a specific mechanism, a bounded mitigation or rollback canary is a proposed next deployment action.",
    "scope": "A conditional choice using surviving alternatives; the mapping does not choose between mitigation and rollback or assert that the condition holds.",
    "provenance": {
