      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span expressly identifies this bounded deployment option when evidence supports a specific mechanism."
    }
  },
  "signal_basis": {
    "component_id": "C051_SIGNAL",
    "value": "An evidence-by-hypothesis comparison identifies reliable, discriminating observations favoring a mechanism, such as queue versus downstream phase-duration patterns or a version association persisting within comparable workloads and execution windows. Sensitivity checks examine the effects of incomplete traces, uncertain phase boundaries, workload, version and combined causes.",
    "scope": "These are proposed observations, assumed to occur for this judgment. Phase comparisons require comparable measurements; surviving explanations are not thereby proven causes.",
